<?php require_once __DIR__ . '/auth.php'; require_login('student'); $subjectId=(int)($_GET['subject']??1); $subject=one('SELECT * FROM subjects WHERE id=?','i',[$subjectId]); $questions=many('SELECT * FROM questions WHERE subject_id=? ORDER BY FIELD(difficulty,\'Easy\',\'Medium\',\'Hard\'),id LIMIT 5','i',[$subjectId]); if(!$subject||!$questions) redirect('practice.php'); $pageTitle='Practice · '.$subject['name']; include 'includes/header.php'; ?><div class="page-head"><div><div class="eyebrow"><?=e($subject['code'])?> / assessment</div><h1><?=e($subject['name'])?> sprint.</h1><p><?=count($questions)?> questions · Immediate feedback · Difficulty adapts to your path</p></div><span class="pill lime">10 min</span></div><form method="post" action="result.php" class="question-card"><input type="hidden" name="subject_id" value="<?=$subjectId?>"><?php foreach($questions as $index=>$question): ?><section class="panel" style="margin-bottom:15px"><div class="panel-head"><small>Question <?=($index+1)?> of <?=count($questions)?></small><span class="pill"><?=e($question['difficulty'])?> · <?=$question['marks']?> pts</span></div><h3><?=e($question['question'])?></h3><?php foreach(['A'=>'option_a','B'=>'option_b','C'=>'option_c','D'=>'option_d'] as $key=>$field): ?><label class="option"><input type="radio" name="answers[<?=$question['id']?>]" value="<?=$key?>"> <span><strong><?=$key?></strong>&nbsp; <?=e($question[$field])?></span></label><?php endforeach; ?></section><?php endforeach; ?><button class="button button-primary" type="submit">Submit assessment ↗</button></form><?php include 'includes/footer.php'; ?>